def analyze_transaction_description(self, transaction: Transaction) -> Dict[str, Any]:
    """
    Analyze a transaction's description for suspicious content using OpenAI GPT-4o.

    Args:
        transaction: The transaction to analyze

    Returns:
        Dict with 'is_suspicious' boolean and optional 'description' field
    """
    if not hasattr(transaction, 'description') or not transaction.description:
        return {'is_suspicious': False, 'message': 'No description to analyze'}

    is_suspicious = analyze_description_for_suspicious_content(transaction.description)

    return {
        'is_suspicious': is_suspicious,
        'description': transaction.description
    }
